head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.gAcptNo;
scwin.gInputSeq;
scwin.gIsurCd;
scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;
scwin.vScrenID = 'ULDSTF25125.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_GetParentValue = function() {
    scwin.gAcptNo = $c.frame.path("../").scwin.gAcptNo;
    scwin.gIsurCd = $c.frame.path("../").scwin.gIsurCd;
    scwin.gInputSeq = $c.frame.path("../").scwin.gInputSeq;
};
scwin.fn_searchCode = function() {
    /*
    00443 - 발행방법
    */
    var arrCid = [{
        cid: "SECU_ISU_METHD_CD",
        cnm: "cmb_SECU_ISU_METHD_CD"
    }];
    var objCod;
    var url = "/CodeAction.do?method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='SECU_ISU_METHD_CD'";
    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
    var strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        //alert('[objCod]'+objCod);
        if (objCod == null) {
            $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "";
        for (j = 1; j <= dts_Cod.getTotalRow(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") == arrCid[i].cid) {
                strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
};
scwin.fn_read_sync = function() {
    var url = "/InvestStatistics.do?method=listSecuIsuRsltAll&inputMessageId=DSCL_SECU_ISU_RSLT_INOUT" + "&SEARCH_TYP=R" + "&ISUR_CD=" + scwin.gIsurCd + "&INPUT_SEQ=" + scwin.gInputSeq + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_SECU_ISU_RSLT.DataID = encodeURI(url);
    dts_SECU_ISU_RSLT.reset();
};
scwin.fn_Save = function() {
    var vIsurCd = $c.stf.getObjectValue(txb_ISUR_CD);
    if (vIsurCd.length != 5) {
        $c.win.alert("[회사코드]를 입력하세요.");
        txb_ISUR_CD.focus();
        return;
    }
    if ($c.stf.getObjectValue(cmb_SECU_ISU_METHD_CD) == "") {
        $c.win.alert("[발행방법]을 선택하세요.");
        cmb_SECU_ISU_METHD_CD.focus();
        return;
    }
    if ($c.stf.getObjectValue(edt_PAY_DD) == "") {
        $c.win.alert("[납입일]을 입력하세요.");
        edt_PAY_DD.focus();
        return;
    }
    //alert(dts_nfaith.text);

    var gJobType = TR_JOB_INSERT;
    var LastJob = '저장';
    if (scwin.gInputSeq != '') {
        gJobType = TR_JOB_UPDATE;
        LastJob = '수정';
    }
    if (!window.confirm($c.stf.getMessageParam("MSG-A006", LastJob))) return;
    scwin.fn_trs(gJobType);
};
scwin.fn_Delete = function() {
    if (scwin.gInputSeq == '') {
        $c.win.alert("삭제대상을 선택하세요.");
        return;
    }
    if (!window.confirm($c.stf.getMessageParam("MSG-A006", '삭제'))) return;
    scwin.fn_trs(TR_JOB_DELETE);
};
scwin.fn_trs = function(jobType) {
    dts_SECU_ISU_RSLT.setCellData(1, "JOB_TYPE", jobType);
    dts_SECU_ISU_RSLT.setCellData(1, "TRANSTR_EMP_NO", js_emp_no);
    var gTrsCd;
    if (jobType == TR_JOB_INSERT) {
        gTrsCd = SCREN_PROCS_TP_CD_02;
    } else if (jobType == TR_JOB_UPDATE) {
        gTrsCd = SCREN_PROCS_TP_CD_03;
    } else if (jobType == TR_JOB_DELETE) {
        gTrsCd = SCREN_PROCS_TP_CD_04;
    }

    //alert(dts_SECU_ISU_RSLT.text);

    trs_Save.Action = "/InvestStatistics.do?method=saveSecuIsuRslt&inputMessageId=DSCL_SECU_ISU_RSLT_INOUT&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + gTrsCd;
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_SECU_ISU_RSLT)";
    trs_Save.Post();
};
scwin.img_ISU_DECSN_FST_BODRESOL_DD_onclick = function() {
    popUpCalendar2(edt_ISU_DECSN_FST_BODRESOL_DD);
};
scwin.img_PAY_DD_onclick = function() {
    popUpCalendar2(edt_PAY_DD);
};
scwin.btn_Save_onclick = function() {
    scwin.fn_Save();
};
scwin.btn_Del_onclick = function() {
    scwin.fn_Delete();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.dts_SECU_ISU_RSLT_OnLoadError = function() {
    $c.stf.alert_error(dts_SECU_ISU_RSLT);
};
scwin.dts_SECU_ISU_RSLT_OnLoadCompleted = function(rowcount) {

};
scwin.trs_Save_OnSuccess = async function() {
    $c.win.alert("성공적으로 처리 되었습니다.");
    // 부모창 reload 처리해야함	
    $c.frame.path("../").fn_list_sync();
    await $c.frame.CloseFrame();
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert('trs_Save.OnFail() :' + trs_Save.ErrorMsg);
};
scwin.txb_ISUR_CD_onblur = function() {
    if (txb_ISUR_CD.getValue() == "") {
        txb_COM_ABBRV.setValue("");
    }
};
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_ABBRV);
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_Item);
    scwin.fn_searchCode();
    scwin.fn_GetParentValue();
    if (scwin.gInputSeq != '') {
        $c.stf.showObj(panel_com_srch, false);
        scwin.fn_read_sync();
        if (scwin.gAcptNo != '') {
            $c.stf.showObj(panel_Button, false);
        }
    } else {
        // 가우스헤더 셋팅
        dts_SECU_ISU_RSLT.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=DSCL_SECU_ISU_RSLT_INOUT";
        dts_SECU_ISU_RSLT.reset();
        dts_SECU_ISU_RSLT.insertRow();
    }
};
